def solve(grid):
    if not grid:
        return []

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Find separator row (first row where all elements are identical)
    sep_row = -1
    for r in range(rows):
        if all(grid[r][c] == grid[r][0] for c in range(cols)):
            sep_row = r
            break

    if sep_row == -1:
        return grid

    # Find separator column (column of 0s in the reference section above sep_row)
    sep_col = -1
    for c in range(cols):
        is_zero_col = True
        for r in range(sep_row):
            if grid[r][c] != 0:
                is_zero_col = False
                break
        if is_zero_col:
            sep_col = c
            break

    if sep_col == -1:
        return grid

    # Build mapping from left region to right region from reference rows
    mapping = {}
    for r in range(sep_row):
        left_val = grid[r][0]
        # Right region starts after sep_col
        if sep_col + 1 < cols:
            right_val = grid[r][sep_col + 1]
        else:
            right_val = grid[r][-1]
        mapping[left_val] = right_val

    # Create reverse mapping
    reverse_mapping = {v: k for k, v in mapping.items()}

    # Create result grid
    result = [row[:] for row in grid]

    # Process rows below separator
    for r in range(sep_row + 1, rows):
        # Check left region (columns 0 to sep_col-1)
        left_is_empty = True
        left_val = 0
        for c in range(sep_col):
            if result[r][c] != 0:
                left_is_empty = False
                left_val = result[r][c]
                break

        # Check right region (columns sep_col+1 to end)
        right_is_empty = True
        right_val = 0
        for c in range(sep_col + 1, cols):
            if result[r][c] != 0:
                right_is_empty = False
                right_val = result[r][c]
                break

        if left_is_empty and not right_is_empty:
            # Fill left region based on right value
            if right_val in reverse_mapping:
                fill_val = reverse_mapping[right_val]
                for c in range(sep_col):
                    result[r][c] = fill_val
        elif right_is_empty and not left_is_empty:
            # Fill right region based on left value
            if left_val in mapping:
                fill_val = mapping[left_val]
                for c in range(sep_col + 1, cols):
                    result[r][c] = fill_val

    return result
